def _rot(qid, options):
    # Deterministic rotation so the right answer is not always listed first in the data file
    # (the app also shuffles at render time).
    return (sum(ord(c) for c in qid) * 3) % len(options)


def _q(qid, cat, question, options, correct, explanation, why=None):
    k = _rot(qid, options)
    options = options[-k:] + options[:-k] if k else options
    correct = (correct + k) % len(options)
    d = {'id': qid, 'cat': cat, 'type': 'mc', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        d['whyTested'] = why
    return d


def _ms(qid, cat, question, options, correct, explanation, why=None):
    k = _rot(qid, options)
    options = options[-k:] + options[:-k] if k else options
    correct = sorted((c + k) % len(options) for c in correct)
    d = {'id': qid, 'cat': cat, 'type': 'ms', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        d['whyTested'] = why
    return d


def _tf(qid, cat, question, answer, explanation):
    return {'id': qid, 'cat': cat, 'type': 'tf', 'question': question, 'answer': answer, 'explanation': explanation}


