# Rotate the madlib options deterministically so the right choice is not always listed first
# (the explanations never refer to position).
for _ml in MADLIBS:
    for _b in _ml['blanks']:
        _n = len(_b['options'])
        _k = (sum(ord(c) for c in _ml['id'] + _b['key']) * 5) % _n
        if _k:
            _b['options'] = _b['options'][-_k:] + _b['options'][:-_k]
            _b['correct'] = (_b['correct'] + _k) % _n
del _ml, _b, _n, _k
